56	/**
57	 * Discovers and loads custom slash commands from .toml files in both the
58	 * user's global config directory and the current project's directory.
59	 *
60	 * This loader is responsible for:
61	 * - Recursively scanning command directories.
62	 * - Parsing and validating TOML files.
63	 * - Adapting valid definitions into executable SlashCommand objects.
64	 * - Handling file system errors and malformed files gracefully.
65	 */
66	export class FileCommandLoader implements ICommandLoader {
67	  private readonly projectRoot: string;
68	  private readonly folderTrustEnabled: boolean;
69	  private readonly isTrustedFolder: boolean;
70	
71	  constructor(private readonly config: Config | null) {
72	    this.folderTrustEnabled = !!config?.getFolderTrust();
73	    this.isTrustedFolder = !!config?.isTrustedFolder();
74	    this.projectRoot = config?.getProjectRoot() || process.cwd();
75	  }
76	
77	  /**
78	   * Loads all commands from user, project, and extension directories.
79	   * Returns commands in order: user → project → extensions (alphabetically).
80	   *
81	   * Order is important for conflict resolution in CommandService:
82	   * - User/project commands (without extensionName) use "last wins" strategy
83	   * - Extension commands (with extensionName) get renamed if conflicts exist
84	   *
85	   * @param signal An AbortSignal to cancel the loading process.
86	   * @returns A promise that resolves to an array of all loaded SlashCommands.
87	   */
88	  async loadCommands(signal: AbortSignal): Promise<SlashCommand[]> {
89	    if (this.folderTrustEnabled && !this.isTrustedFolder) {
90	      return [];
91	    }
92	
93	    const allCommands: SlashCommand[] = [];
94	    const globOptions = {
95	      nodir: true,
96	      dot: true,
97	      signal,
98	      follow: true,
99	    };
100	
101	    // Load commands from each directory
102	    const commandDirs = this.getCommandDirectories();
103	    for (const dirInfo of commandDirs) {
104	      try {
105	        const files = await glob('**/*.toml', {
106	          ...globOptions,
107	          cwd: dirInfo.path,
108	        });
109	
110	        const commandPromises = files.map((file) =>
111	          this.parseAndAdaptFile(
112	            path.join(dirInfo.path, file),
113	            dirInfo.path,
114	            dirInfo.extensionName,
115	            dirInfo.extensionId,
116	          ),
117	        );
118	
119	        const commands = (await Promise.all(commandPromises)).filter(
120	          (cmd): cmd is SlashCommand => cmd !== null,
121	        );
122	
123	        // Add all commands without deduplication
124	        allCommands.push(...commands);
125	      } catch (error) {
126	        if (
127	          !signal.aborted &&
128	          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
129	          (error as { code?: string })?.code !== 'ENOENT'
130	        ) {
131	          coreEvents.emitFeedback(
132	            'error',
133	            `[FileCommandLoader] Error loading commands from ${dirInfo.path}:`,
134	            error,
135	          );
136	        }
137	      }
138	    }
139	
140	    return allCommands;
141	  }
142	
143	  /**
144	   * Get all command directories in order for loading.
145	   * User commands → Project commands → Extension commands
146	   * This order ensures extension commands can detect all conflicts.
147	   */
148	  private getCommandDirectories(): CommandDirectory[] {
149	    const dirs: CommandDirectory[] = [];
150	
151	    const storage = this.config?.storage ?? new Storage(this.projectRoot);
152	
153	    // 1. User commands
154	    dirs.push({ path: Storage.getUserCommandsDir() });
155	
156	    // 2. Project commands (override user commands)
157	    dirs.push({ path: storage.getProjectCommandsDir() });
158	
159	    // 3. Extension commands (processed last to detect all conflicts)
160	    if (this.config) {
161	      const activeExtensions = this.config
162	        .getExtensions()
163	        .filter((ext) => ext.isActive)
164	        .sort((a, b) => a.name.localeCompare(b.name)); // Sort alphabetically for deterministic loading
165	
166	      const extensionCommandDirs = activeExtensions.map((ext) => ({
167	        path: path.join(ext.path, 'commands'),
168	        extensionName: ext.name,
169	        extensionId: ext.id,
170	      }));
171	
172	      dirs.push(...extensionCommandDirs);
173	    }
174	
175	    return dirs;
176	  }
